<script setup>import{onMounted,reactive,ref}from'vue';import{showSuccessToast}from'vant';import{api}from'../api/crm';const tasks=ref([]),customers=ref([]),show=ref(false),form=reactive({customerId:'',title:'',description:'',dueDate:'',priority:'MEDIUM'});async function load(){[tasks.value,customers.value]=await Promise.all([api.tasks(),api.customers('')])}async function add(){await api.createTask({...form,customerId:form.customerId?Number(form.customerId):null,dueDate:form.dueDate||null});show.value=false;form.title='';form.description='';form.dueDate='';showSuccessToast('任务已创建');load()}async function toggle(t){await api.setTask(t.id,!t.completed);load()}async function remove(id){await api.deleteTask(id);load()}onMounted(load)</script>
<template><div class="page safe-top"><van-nav-bar title="销售任务" left-arrow @click-left="$router.back()" right-text="新建" @click-right="show=true"/><section v-for="task in tasks" :key="task.id" class="task card" :class="{completed:task.completed}"><van-checkbox :model-value="task.completed" checked-color="#2856a8" @click="toggle(task)"/><div class="content"><div class="list-title">{{task.title}}</div><div v-if="task.customerName" class="customer"><van-icon name="friends-o"/> {{task.customerName}}</div><div class="muted">{{task.description||'暂无描述'}}</div><div class="meta"><span :class="`priority ${task.priority.toLowerCase()}`">{{{HIGH:'高',MEDIUM:'中',LOW:'低'}[task.priority]}}优先级</span><span>{{task.dueDate||'无截止日期'}}</span></div></div><van-icon name="delete-o" color="#a4b0b3" @click="remove(task.id)"/></section><div v-if="!tasks.length" class="empty">销售任务已全部完成</div><van-popup v-model:show="show" position="bottom" round><div class="form"><h2>新建销售任务</h2><label class="select-row"><span>关联客户</span><select v-model="form.customerId"><option value="">不关联客户</option><option v-for="c in customers" :key="c.id" :value="c.id">{{c.shortName||c.name}}</option></select></label><van-field v-model="form.title" label="任务标题" placeholder="要推进什么？"/><van-field v-model="form.description" label="任务描述" type="textarea" rows="2"/><van-field v-model="form.dueDate" label="截止日期" type="date"/><van-radio-group v-model="form.priority" direction="horizontal"><van-radio name="HIGH">高</van-radio><van-radio name="MEDIUM">中</van-radio><van-radio name="LOW">低</van-radio></van-radio-group><button class="action-btn" :disabled="!form.title" @click="add">创建任务</button></div></van-popup></div></template>
<style scoped>.van-nav-bar{background:transparent;margin:-8px -16px 14px}.task{display:flex;gap:13px;align-items:flex-start}.task.completed{opacity:.55}.task.completed .list-title{text-decoration:line-through}.content{flex:1}.customer{font-size:12px;color:#2856a8;margin:7px 0}.meta{display:flex;gap:12px;margin-top:10px;color:#89999e;font-size:11px}.priority{padding:2px 6px;border-radius:7px}.high{background:#ffeded;color:#d65353}.medium{background:#fff4dc;color:#ad761e}.low{background:#e9f5ef;color:#37825b}.form{padding:18px 20px 32px}.form h2{margin:0 0 14px}.van-radio-group{padding:18px 16px}.select-row{display:flex;align-items:center;padding:12px 16px;border-bottom:1px solid #eee;font-size:14px}.select-row span{width:90px;color:#646b75}.select-row select{flex:1;border:0;background:#fff}.action-btn{margin-top:10px}</style>
